// Slack Block Kit approval message for a sensitive bot/* PR.
const pr = $('GitHub PR Events').first().json.body.pull_request;
const title = pr.title || 'Brain update';
let body = String(pr.body || '').trim();
if (body.length > 900) body = body.substring(0, 900) + '…';
const value = JSON.stringify({ pr: pr.number });
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Brain update — approval needed', emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: '*' + title + '*\n' + (body || '_no description_') } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: 'PR #' + pr.number + ' · <' + pr.html_url + '|view diff>' }] },
  { type: 'actions', elements: [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: '✅ Approve & Merge' }, action_id: 'ssot_approve', value },
    { type: 'button', style: 'danger', text: { type: 'plain_text', text: '❌ Reject' }, action_id: 'ssot_reject', value }
  ] }
];
return [{ json: { blocks_json: JSON.stringify({ blocks: blocks }), fallback_text: 'Brain update: ' + title + ' (PR #' + pr.number + ')' } }];

// Slack interactivity payloads arrive as form-encoded: body.payload = JSON string.
const raw = $json.body && $json.body.payload;
if (!raw) return [];
const p = typeof raw === 'string' ? JSON.parse(raw) : raw;
const action = (p.actions && p.actions[0]) || {};
let prNumber = null;
try { prNumber = JSON.parse(action.value || '{}').pr; } catch (e) {}
if (!prNumber) return [];
return [{ json: {
  action_id: action.action_id,
  pr_number: prNumber,
  response_url: p.response_url,
  clicked_by: (p.user && (p.user.name || p.user.username)) || 'unknown'
} }];

// Approve path: squash-merge the bot PR, then update the Slack message.
const d = $json;
const token = 'REPLACE_WITH_GITHUB_TOKEN';
const repoApi = 'https://api.github.com/repos/OWNER/REPO';
const gh = { Authorization: 'Bearer ' + token, Accept: 'application/vnd.github.v3+json' };
let resultText;
try {
  await this.helpers.httpRequest({ method: 'PUT', url: repoApi + '/pulls/' + d.pr_number + '/merge', headers: gh, body: { merge_method: 'squash' } });
  resultText = ':white_check_mark: *Approved & merged* PR #' + d.pr_number + ' · by ' + d.clicked_by;
} catch (err) {
  resultText = ':warning: Merge of PR #' + d.pr_number + ' failed: ' + err.message + ' — handle it directly on GitHub.';
}
try {
  await this.helpers.httpRequest({ method: 'POST', url: d.response_url, body: { replace_original: true, text: resultText } });
} catch (e) {}
return [{ json: { ...d, result: resultText } }];

// Reject path: comment + close the bot PR, then update the Slack message.
const d = $json;
const token = 'REPLACE_WITH_GITHUB_TOKEN';
const repoApi = 'https://api.github.com/repos/OWNER/REPO';
const gh = { Authorization: 'Bearer ' + token, Accept: 'application/vnd.github.v3+json' };
let resultText;
try {
  await this.helpers.httpRequest({ method: 'POST', url: repoApi + '/issues/' + d.pr_number + '/comments', headers: gh, body: { body: 'Rejected via Slack by ' + d.clicked_by + '. Closing without merge.' } });
  await this.helpers.httpRequest({ method: 'PATCH', url: repoApi + '/pulls/' + d.pr_number, headers: gh, body: { state: 'closed' } });
  resultText = ':x: *Rejected* PR #' + d.pr_number + ' · by ' + d.clicked_by;
} catch (err) {
  resultText = ':warning: Reject of PR #' + d.pr_number + ' failed: ' + err.message + ' — handle it directly on GitHub.';
}
try {
  await this.helpers.httpRequest({ method: 'POST', url: d.response_url, body: { replace_original: true, text: resultText } });
} catch (e) {}
return [{ json: { ...d, result: resultText } }];
